insert into public.recipes (slug, title, dish_id, minutes, servings, ingredients, steps, reviewed) values
  ('chicken-karahi', 'Home-Style Chicken Karahi', (select id from public.dishes where slug = 'chicken-karahi'), 45, 4, '[{"item":"chicken","quantity":"1 kg"},{"item":"tomatoes","quantity":"5 medium"},{"item":"ginger garlic paste","quantity":"2 tablespoons"},{"item":"green chilies","quantity":"4"},{"item":"cooking oil","quantity":"1/2 cup"},{"item":"red chili flakes","quantity":"1 teaspoon"},{"item":"black pepper powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"cumin seeds","quantity":"1 teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"fresh coriander","quantity":"2 tablespoons"}]'::jsonb, '["Heat cooking oil in a karahi or deep wok over medium heat.","Add the chicken and ginger garlic paste, frying until the chicken changes color.","Cut the tomatoes in half, place them cut-side down over the chicken, cover, and cook for 10 minutes.","Remove the tomato skins, mash the tomatoes into the gravy, and stir well.","Add salt, red chili flakes, cumin seeds, coriander powder, and black pepper powder.","Cook on high heat until the oil separates from the masala and the chicken is tender.","Garnish with sliced green chilies and fresh coriander before serving hot with naan."]'::jsonb, true),
  ('chicken-biryani', 'Pakistani Chicken Biryani', (select id from public.dishes where slug = 'chicken-biryani'), 60, 4, '[{"item":"Basmati rice","quantity":"2 cups"},{"item":"Chicken","quantity":"500 grams"},{"item":"Yogurt","quantity":"1 cup"},{"item":"Onions","quantity":"2 large"},{"item":"Tomatoes","quantity":"2 medium"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Biryani masala","quantity":"3 tablespoons"},{"item":"Cooking oil","quantity":"half cup"},{"item":"Fresh mint leaves","quantity":"half cup"},{"item":"Fresh coriander leaves","quantity":"half cup"},{"item":"Green chilies","quantity":"4 units"}]'::jsonb, '["Soak basmati rice in water for thirty minutes and boil until eighty percent cooked.","Slice the onions thinly and fry them in oil until golden brown, then set half aside.","Add ginger garlic paste and chicken to the remaining onions in the pot, cooking until the color changes.","Stir in chopped tomatoes, yogurt, and biryani masala, cooking until the oil separates from the gravy.","Layer the partially boiled rice over the prepared chicken curry.","Top with the reserved fried onions, fresh mint, coriander, and green chilies.","Cover the pot tightly and let it steam on very low heat for twenty minutes before serving."]'::jsonb, true),
  ('chicken-pulao', 'Simple Pakistani Chicken Pulao', (select id from public.dishes where slug = 'chicken-pulao'), 45, 4, '[{"item":"Basmati rice","quantity":"2 cups"},{"item":"Chicken, cut into pieces","quantity":"500 grams"},{"item":"Onion, thinly sliced","quantity":"1 large"},{"item":"Tomatoes, chopped","quantity":"2 medium"},{"item":"Ginger and garlic paste","quantity":"1 tablespoon"},{"item":"Yogurt","quantity":"1/2 cup"},{"item":"Cooking oil or ghee","quantity":"1/4 cup"},{"item":"Whole spices (cumin seeds, black cardamom, cloves, cinnamon stick, bay leaf)","quantity":"1 tablespoon"},{"item":"Coriander and cumin powder","quantity":"1 tablespoon"},{"item":"Salt","quantity":"1.5 tablespoons"},{"item":"Water","quantity":"3.5 cups"},{"item":"Green chilies","quantity":"3"}]'::jsonb, '["Soak the basmati rice in water for 30 minutes, then drain.","Heat oil in a large pot and fry the sliced onions until golden brown.","Add the whole spices, ginger and garlic paste, and cook for one minute.","Add the chicken pieces and cook until the color changes to white.","Stir in the chopped tomatoes, yogurt, coriander and cumin powder, and salt.","Cover and cook until the chicken is tender and oil separates from the masala.","Pour in the water and add green chilies, then bring to a boil.","Add the soaked rice, gently stir, and cook on medium heat until most of the water is absorbed.","Cover the pot with a tight lid and simmer on very low heat for 15 minutes.","Fluff the rice gently with a fork and serve hot."]'::jsonb, true),
  ('chicken-korma', 'Traditional Pakistani Chicken Korma', (select id from public.dishes where slug = 'chicken-korma'), 45, 4, '[{"item":"Chicken","quantity":"1 kg"},{"item":"Yogurt","quantity":"1 cup"},{"item":"Onions","quantity":"2 large"},{"item":"Cooking oil or ghee","quantity":"half cup"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Garam masala powder","quantity":"half teaspoon"},{"item":"Green cardamom pods","quantity":"4"},{"item":"Cloves","quantity":"4"},{"item":"Water","quantity":"1 cup"}]'::jsonb, '["Slice the onions thinly and fry them in hot oil until golden brown, then crush them after cooling.","In the same oil, add green cardamom and cloves, followed by the ginger garlic paste.","Add the chicken pieces and cook on medium heat until the color changes to white.","Mix in the red chili powder, coriander powder, and salt, stirring well for a few minutes.","Beat the yogurt and add it to the pot along with the crushed fried onions.","Pour in the water, cover the pot with a lid, and let it simmer on low heat until the chicken is tender and oil separates.","Sprinkle garam masala powder on top and serve hot with naan or rice."]'::jsonb, true),
  ('chicken-tikka', 'Pakistani Chicken Tikka', (select id from public.dishes where slug = 'chicken-tikka'), 45, 4, '[{"item":"Chicken pieces","quantity":"1 kg"},{"item":"Plain yogurt","quantity":"1 cup"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Lemon juice","quantity":"3 tablespoons"},{"item":"Red chili powder","quantity":"1.5 teaspoons"},{"item":"Turmeric powder","quantity":"0.5 teaspoon"},{"item":"Garam masala powder","quantity":"1 teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"Salt","quantity":"1.5 teaspoons"},{"item":"Cooking oil","quantity":"3 tablespoons"}]'::jsonb, '["Clean the chicken pieces and make deep cuts with a knife.","In a large bowl, mix yogurt, ginger garlic paste, lemon juice, and all the spices together.","Add salt and cooking oil into the yogurt mixture and stir well.","Coat the chicken pieces thoroughly with the marinade, ensuring it enters the cuts.","Cover the bowl and let the chicken marinate for at least two hours in the refrigerator.","Preheat the oven or a heavy skillet over medium heat.","Place the marinated chicken pieces on the grill or in the pan.","Cook for about 20 to 25 minutes, turning occasionally, until the chicken is tender and slightly charred on the edges.","Serve hot with sliced onions and fresh mint chutney."]'::jsonb, true),
  ('aloo-gosht', 'Aloo Gosht', (select id from public.dishes where slug = 'aloo-gosht'), 60, 4, '[{"item":"Mutton","quantity":"500 grams"},{"item":"Potatoes, peeled and cut into halves","quantity":"3 large"},{"item":"Onions, thinly sliced","quantity":"2 medium"},{"item":"Tomatoes, chopped","quantity":"2 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Yogurt, beaten","quantity":"1/2 cup"},{"item":"Cooking oil","quantity":"1/2 cup"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"1/2 teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Garam masala powder","quantity":"1/2 teaspoon"},{"item":"Fresh coriander leaves, chopped","quantity":"2 tablespoons"}]'::jsonb, '["Heat oil in a pot and fry the sliced onions until golden brown.","Add ginger garlic paste and meat, then sauté for five minutes until the color changes.","Add red chili powder, turmeric powder, coriander powder, and salt.","Stir in the chopped tomatoes and cook until they become soft.","Add beaten yogurt and fry the mixture well until oil separates.","Pour in two cups of water, cover, and simmer until the meat is almost tender.","Add the potato pieces and cook until both the meat and potatoes are fully tender.","Sprinkle garam masala and fresh coriander leaves on top before serving."]'::jsonb, true),
  ('mutton-karahi', 'Traditional Mutton Karahi', (select id from public.dishes where slug = 'mutton-karahi'), 60, 4, '[{"item":"Mutton on the bone","quantity":"1 kg"},{"item":"Ripe tomatoes","quantity":"500 grams"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Cooking oil or ghee","quantity":"1 cup"},{"item":"Green chilies","quantity":"5 to 6"},{"item":"Fresh coriander leaves","quantity":"1/2 cup"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Red chili flakes","quantity":"1 teaspoon"},{"item":"Crushed black pepper","quantity":"1 teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"water","quantity":"1/2 cup"}]'::jsonb, '["Heat oil or ghee in a traditional karahi or deep heavy-bottomed wok.","Add the mutton and ginger garlic paste, frying on high heat until the meat changes color.","Add water and salt, then cover and cook on medium heat until the mutton is tender.","Cut the tomatoes in half lengthwise and place them cut-side down over the meat.","Cover the karahi for 10 minutes so the tomato skins soften, then remove the skins using tongs.","Mash the softened tomatoes into the gravy and fry the mixture on high heat until the oil separates.","Add red chili flakes, crushed black pepper, and coriander powder, stirring well.","Add slit green chilies and half of the fresh coriander leaves, then simmer for another 2 minutes.","Garnish with the remaining fresh coriander and serve hot with naan."]'::jsonb, true),
  ('beef-pulao', 'Simple Pakistani Beef Pulao', (select id from public.dishes where slug = 'beef-pulao'), 60, 4, '[{"item":"beef","quantity":"500 grams"},{"item":"basmati rice","quantity":"2 cups"},{"item":"onion","quantity":"1 large"},{"item":"ginger garlic paste","quantity":"2 tablespoons"},{"item":"tomatoes","quantity":"2 medium"},{"item":"yogurt","quantity":"half cup"},{"item":"whole spices","quantity":"1 tablespoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"cumin seeds","quantity":"1 teaspoon"},{"item":"salt","quantity":"to taste"},{"item":"cooking oil","quantity":"half cup"},{"item":"water","quantity":"4 cups"}]'::jsonb, '["Wash and soak the basmati rice for thirty minutes.","Heat oil in a heavy-bottomed pot and fry sliced onions until golden brown.","Add whole spices and ginger garlic paste, frying for a minute.","Add beef pieces and cook until the meat changes color.","Add chopped tomatoes, yogurt, coriander powder, cumin seeds, and salt, cooking until oil separates.","Pour in water, cover, and simmer on medium heat until the beef is tender.","Add the soaked rice to the boiling beef broth and stir gently.","Cook uncovered until most of the water is absorbed.","Cover the pot tightly and let the rice steam on low heat for ten minutes before serving."]'::jsonb, true),
  ('nihari', 'Traditional Beef Nihari', (select id from public.dishes where slug = 'nihari'), 180, 6, '[{"item":"Beef shank with bone","quantity":"1 kg"},{"item":"Nihari masala powder","quantity":"3 tablespoons"},{"item":"Cooking oil","quantity":"1 cup"},{"item":"Ghee","quantity":"3 tablespoons"},{"item":"Sliced onion","quantity":"1 large"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Whole wheat flour","quantity":"4 tablespoons"},{"item":"Water","quantity":"8 cups"},{"item":"Fresh ginger julienned","quantity":"2 tablespoons"},{"item":"Fresh coriander chopped","quantity":"3 tablespoons"},{"item":"Green chilies sliced","quantity":"4 pieces"},{"item":"Lemon wedges","quantity":"4 pieces"}]'::jsonb, '["Heat oil in a large heavy-bottomed pot and fry the sliced onion until golden brown.","Add ginger garlic paste and beef shank pieces, then fry well until the meat changes color.","Add the nihari masala powder and half a cup of water, and sauté the mixture for 5 minutes.","Pour in 7 cups of water, bring to a boil, then cover and simmer on low heat for 2 to 3 hours until the meat is tender.","In a separate bowl, mix the whole wheat flour with 1 cup of water to make a smooth, lump-free paste.","Slowly pour the flour paste into the simmering stew while stirring constantly to thicken the gravy.","Cover and cook on low heat for another 20 minutes until the oil separates to the top.","In a small pan, melt the ghee and pour it over the nihari just before serving.","Garnish with julienned ginger, chopped fresh coriander, sliced green chilies, and serve hot with naan."]'::jsonb, true),
  ('keema', 'Pakistani Style Bhuna Keema', (select id from public.dishes where slug = 'keema'), 35, 4, '[{"item":"minced beef","quantity":"500 grams"},{"item":"onions, finely sliced","quantity":"2 medium"},{"item":"tomatoes, chopped","quantity":"2 medium"},{"item":"ginger paste","quantity":"1 tablespoon"},{"item":"garlic paste","quantity":"1 tablespoon"},{"item":"cooking oil","quantity":"4 tablespoons"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"half teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"garam masala powder","quantity":"half teaspoon"},{"item":"fresh coriander leaves","quantity":"2 tablespoons"},{"item":"green chilies","quantity":"2"}]'::jsonb, '["Heat cooking oil in a pot and add sliced onions. Fry until golden brown.","Add ginger paste and garlic paste to the pot. Sauté for one minute until aromatic.","Add minced meat, salt, red chili powder, turmeric powder, and coriander powder.","Cook and stir the meat on high heat for 5 to 7 minutes until its color changes.","Add chopped tomatoes and mix well with the meat.","Cover the pot and let it cook on low heat for 10 minutes until the meat is tender and tomatoes are soft.","Remove the lid and increase the heat to bhuna (fry) the keema until oil separates from the masala.","Sprinkle garam masala, chopped green chilies, and fresh coriander leaves on top.","Serve hot with fresh roti or naan."]'::jsonb, true),
  ('kofta', 'Traditional Pakistani Beef Kofta Curry', (select id from public.dishes where slug = 'kofta'), 60, 4, '[{"item":"Minced beef","quantity":"500 grams"},{"item":"Onion","quantity":"2 medium"},{"item":"Ginger garlic paste","quantity":"2 tablespoons"},{"item":"Gram flour","quantity":"2 tablespoons"},{"item":"Yogurt","quantity":"1 cup"},{"item":"Cooking oil","quantity":"half cup"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"Turmeric powder","quantity":"half teaspoon"},{"item":"Garam masala","quantity":"1 teaspoon"},{"item":"Salt","quantity":"to taste"}]'::jsonb, '["Finely chop one onion and keep the other onion sliced for the gravy.","Mix minced beef, chopped onion, half of the ginger garlic paste, gram flour, and basic spices in a bowl.","Shape the spiced meat mixture into small round balls called kofta.","Heat oil in a pot and fry the sliced onions until golden brown, then remove and blend them with yogurt.","In the same oil, add the remaining ginger garlic paste and whole spices.","Pour in the yogurt and onion paste mixture and cook until oil separates.","Carefully place the meat kofta into the gravy without stirring too much.","Cover the pot and let it simmer on low heat until the kofta are fully cooked and tender.","Sprinkle garam masala and fresh coriander leaves on top before serving."]'::jsonb, true),
  ('palak-gosht', 'Pakistani Palak Gosht', (select id from public.dishes where slug = 'palak-gosht'), 60, 4, '[{"item":"Mutton","quantity":"500 grams"},{"item":"Spinach (palak)","quantity":"1 kg"},{"item":"Onion","quantity":"2 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Tomatoes","quantity":"2 medium"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"half teaspoon"},{"item":"Coriander powder","quantity":"1 teaspoon"},{"item":"Salt","quantity":"to taste"},{"item":"Cooking oil or ghee","quantity":"half cup"},{"item":"Garam masala powder","quantity":"half teaspoon"}]'::jsonb, '["Wash and clean the spinach leaves thoroughly, then boil them in water for ten minutes and blend into a coarse paste.","Heat oil in a pot and fry the sliced onions until golden brown.","Add ginger garlic paste and sauté for one minute.","Add the meat and cook on high heat until the color changes.","Add chopped tomatoes, red chili powder, turmeric, coriander powder, and salt.","Add a cup of water, cover, and cook until the meat becomes tender.","Add the blended spinach to the cooked meat and mix well.","Cook on medium heat, stirring occasionally, until the oil separates from the spinach and gravy.","Sprinkle garam masala powder on top and serve hot with naan or boiled rice."]'::jsonb, true),
  ('machli', 'Pakistani Style Fried Fish Machli', (select id from public.dishes where slug = 'machli'), 30, 4, '[{"item":"fish fillets","quantity":"500 grams"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"1/2 teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"cumin powder","quantity":"1/2 teaspoon"},{"item":"carom seeds ajwain","quantity":"1/2 teaspoon"},{"item":"lemon juice","quantity":"2 tablespoons"},{"item":"gram flour besan","quantity":"3 tablespoons"},{"item":"salt","quantity":"1 teaspoon"},{"item":"cooking oil","quantity":"for frying"}]'::jsonb, '["Wash the fish fillets thoroughly and pat them completely dry with a paper towel.","In a mixing bowl, combine ginger garlic paste, red chili powder, turmeric powder, coriander powder, cumin powder, carom seeds, lemon juice, and salt.","Rub this spice mixture evenly over all the fish pieces.","Sprinkle the gram flour over the coated fish and mix gently so it sticks well.","Let the fish marinate for at least 15 minutes at room temperature.","Heat cooking oil in a deep frying pan over medium-high flame.","Carefully place the fish pieces into the hot oil without overcrowding the pan.","Fry the fish for 3 to 4 minutes on each side until golden brown and crispy.","Remove the fried fish and drain excess oil on paper towels.","Serve hot with lemon wedges and mint chutney."]'::jsonb, true),
  ('fish-curry', 'Pakistani Fish Curry', (select id from public.dishes where slug = 'fish-curry'), 40, 4, '[{"item":"Fish fillets","quantity":"750 grams"},{"item":"Onion","quantity":"2 medium"},{"item":"Tomatoes","quantity":"3 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Cooking oil","quantity":"half cup"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"half teaspoon"},{"item":"Coriander powder","quantity":"1 tablespoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Garam masala powder","quantity":"half teaspoon"},{"item":"Fresh coriander leaves","quantity":"a handful"}]'::jsonb, '["Clean the fish pieces and apply a little salt and turmeric, then set aside for ten minutes.","Heat oil in a pan and fry the sliced onions until golden brown.","Add ginger garlic paste and chopped tomatoes to the pan, cooking until tomatoes are soft.","Stir in red chili powder, coriander powder, turmeric powder, and salt.","Fry the masala well until the oil separates from the mixture.","Gently place the fish pieces into the pan in a single layer.","Add a cup of water, cover the pan with a lid, and simmer on low heat for ten minutes without stirring too much.","Sprinkle garam masala and fresh coriander leaves on top before turning off the heat."]'::jsonb, true),
  ('chana-daal', 'Home-Style Chana Daal', (select id from public.dishes where slug = 'chana-daal'), 45, 4, '[{"item":"split chana daal","quantity":"1 cup"},{"item":"water","quantity":"3 cups"},{"item":"cooking oil","quantity":"4 tablespoons"},{"item":"onion","quantity":"1 medium"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"tomato","quantity":"1 medium"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"0.5 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"garam masala","quantity":"0.5 teaspoon"},{"item":"fresh cilantro","quantity":"2 tablespoons"}]'::jsonb, '["Wash and soak the chana daal in water for 30 minutes, then drain.","Heat oil in a pot and add finely sliced onions.","Fry the onions until golden brown.","Add ginger garlic paste and fry for one minute.","Add chopped tomatoes, red chili powder, turmeric powder, and salt.","Cook the masala until tomatoes become soft and oil separates.","Add the soaked daal and 3 cups of water to the pot.","Cover and cook on medium-low heat until the daal is soft and tender.","Sprinkle garam masala and chopped cilantro on top before serving."]'::jsonb, true),
  ('maash-daal', 'Pakistani Style Maash Daal', (select id from public.dishes where slug = 'maash-daal'), 45, 4, '[{"item":"split white maash daal","quantity":"1 cup"},{"item":"cooking oil","quantity":"4 tablespoons"},{"item":"onion","quantity":"1 medium"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"tomatoes","quantity":"2 medium"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"1/2 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"garam masala powder","quantity":"1/2 teaspoon"},{"item":"fresh coriander","quantity":"2 tablespoons"},{"item":"green chilies","quantity":"2"},{"item":"water","quantity":"2 cups"}]'::jsonb, '["Wash the maash daal thoroughly and soak it in water for at least 30 minutes.","Heat oil in a pan and add sliced onions, frying them until golden brown.","Add ginger garlic paste to the onions and sauté for a minute until fragrant.","Add chopped tomatoes, red chili powder, turmeric powder, and salt.","Cook the masala mixture on medium heat until the tomatoes turn soft and oil separates.","Drain the soaked daal and add it to the pan.","Stir-fry the daal with the masala for 3 minutes.","Pour in 2 cups of water, cover the pan, and cook on low heat until the daal is tender and water is absorbed.","Sprinkle garam masala powder, chopped green chilies, and fresh coriander on top.","Cover and let it steam on very low heat for 5 minutes before serving."]'::jsonb, true),
  ('mixed-daal', 'Homestyle Mixed Daal', (select id from public.dishes where slug = 'mixed-daal'), 45, 4, '[{"item":"Yellow moong daal","quantity":"0.5 cup"},{"item":"Red masoor daal","quantity":"0.5 cup"},{"item":"Chana daal","quantity":"0.25 cup"},{"item":"Water","quantity":"4 cups"},{"item":"Oil or ghee","quantity":"4 tablespoons"},{"item":"Onion","quantity":"1 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Tomato","quantity":"1 medium"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"0.5 teaspoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Cumin seeds","quantity":"1 teaspoon"},{"item":"Fresh coriander","quantity":"2 tablespoons"}]'::jsonb, '["Wash all the lentils thoroughly and soak them in water for thirty minutes.","In a pot, add the soaked lentils, four cups of water, turmeric powder, and salt.","Bring to a boil, then cover and simmer on medium heat until the lentils are completely soft and mashed.","In a separate pan, heat oil or ghee and add sliced onions, frying until golden brown.","Add ginger garlic paste and chopped tomatoes to the pan, cooking until tomatoes turn soft.","Stir in red chili powder and cumin seeds, frying the masala for two minutes.","Pour the cooked lentil mixture into the pan with the masala and mix well.","Simmer everything together for five minutes so the flavors blend nicely.","Garnish with fresh coriander and serve hot with boiled rice or flatbread."]'::jsonb, true),
  ('daal-kaddu', 'Daal Kaddu', (select id from public.dishes where slug = 'daal-kaddu'), 45, 4, '[{"item":"yellow moong daal","quantity":"1 cup"},{"item":"bottlegourd kaddu, peeled and cubed","quantity":"2 cups"},{"item":"oil or ghee","quantity":"4 tablespoons"},{"item":"onion, finely sliced","quantity":"1 medium"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"tomato, chopped","quantity":"1 medium"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"half teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"to taste"},{"item":"water","quantity":"3 cups"},{"item":"garam masala powder","quantity":"half teaspoon"},{"item":"fresh cilantro, chopped","quantity":"2 tablespoons"}]'::jsonb, '["Wash the moong daal thoroughly and soak it in water for 20 minutes.","Heat oil or ghee in a pot and add sliced onions, frying until golden brown.","Add ginger garlic paste and sauté for a minute until aromatic.","Add chopped tomatoes, red chili powder, turmeric, coriander powder, and salt.","Cook the masala well, splashing a little water until the tomatoes turn soft and oil separates.","Add the cubed kaddu and soaked daal to the pot, stirring well with the masala.","Pour in 3 cups of water and bring the mixture to a boil.","Cover the pot with a lid, lower the heat, and simmer for 30 minutes until the daal and kaddu are completely tender.","Mash gently with the back of a spoon if a smoother texture is desired.","Sprinkle garam masala and fresh cilantro on top before serving hot with chapati or boiled rice."]'::jsonb, true),
  ('choley', 'Pakistani Choley', (select id from public.dishes where slug = 'choley'), 45, 4, '[{"item":"Boiled chickpeas","quantity":"2 cups"},{"item":"Chopped onions","quantity":"1 medium"},{"item":"Chopped tomatoes","quantity":"2 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Cooking oil","quantity":"4 tablespoons"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"0.5 teaspoon"},{"item":"Coriander powder","quantity":"1 teaspoon"},{"item":"Garam masala powder","quantity":"0.5 teaspoon"},{"item":"Salt","quantity":"to taste"},{"item":"Fresh coriander leaves","quantity":"2 tablespoons"}]'::jsonb, '["Heat cooking oil in a pan and fry the chopped onions until golden brown.","Add ginger garlic paste and sauté for one minute until fragrant.","Add chopped tomatoes, red chili powder, turmeric powder, coriander powder, and salt.","Cook the masala mixture on medium heat until the tomatoes turn soft and oil separates.","Add the boiled chickpeas along with half a cup of water into the pan.","Cover the lid and let it simmer on low heat for ten minutes.","Sprinkle garam masala powder and fresh coriander leaves on top before serving."]'::jsonb, true),
  ('lobia', 'Pakistani Style Lobia Masala', (select id from public.dishes where slug = 'lobia'), 45, 4, '[{"item":"black-eyed peas","quantity":"2 cups"},{"item":"oil","quantity":"4 tablespoons"},{"item":"onion","quantity":"1 medium"},{"item":"ginger paste","quantity":"1 teaspoon"},{"item":"garlic paste","quantity":"1 teaspoon"},{"item":"tomatoes","quantity":"2 medium"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"0.5 teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"garam masala","quantity":"0.5 teaspoon"},{"item":"fresh cilantro","quantity":"2 tablespoons"}]'::jsonb, '["Soak the black-eyed peas in water for a few hours and then boil until tender.","Heat oil in a pot and fry the chopped onions until golden brown.","Add ginger paste and garlic paste to the pot and sauté for a minute.","Add chopped tomatoes, red chili powder, turmeric powder, coriander powder, and salt.","Cook the masala well until the oil separates from the tomato mixture.","Add the boiled black-eyed peas along with some water to the pot and mix well.","Cover and simmer on low heat for 10 minutes so the flavors blend together.","Sprinkle garam masala and chopped fresh cilantro on top before serving with roti or rice."]'::jsonb, true),
  ('bhindi', 'Pakistani Bhindi Masala', (select id from public.dishes where slug = 'bhindi'), 30, 4, '[{"item":"okra (bhindi), washed and cut into pieces","quantity":"500 grams"},{"item":"onions, sliced","quantity":"2 medium"},{"item":"tomatoes, chopped","quantity":"2 medium"},{"item":"cooking oil","quantity":"4 tablespoons"},{"item":"ginger garlic paste","quantity":"1 teaspoon"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"0.5 teaspoon"},{"item":"coriander powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"dried mango powder (amchur)","quantity":"0.5 teaspoon"}]'::jsonb, '["Ensure the okra is completely dry after washing, then cut into half-inch pieces.","Heat two tablespoons of oil in a pan and fry the okra until lightly browned and slightly tender. Remove and set aside.","In the same pan, add the remaining oil and sauté the sliced onions until translucent.","Add the ginger garlic paste and fry for a minute until fragrant.","Add the chopped tomatoes, red chili powder, turmeric powder, coriander powder, and salt.","Cook the masala on medium heat until the oil separates and the tomatoes are soft.","Gently fold in the fried okra and dried mango powder into the tomato onion masala.","Cover the pan with a lid and let it simmer on low heat for ten minutes, stirring occasionally.","Serve hot with freshly made chapati or paratha."]'::jsonb, true),
  ('aloo-palak', 'Aloo Palak', (select id from public.dishes where slug = 'aloo-palak'), 40, 4, '[{"item":"Spinach","quantity":"500 grams"},{"item":"Potatoes","quantity":"3 medium"},{"item":"Cooking oil","quantity":"4 tablespoons"},{"item":"Onion","quantity":"1 medium"},{"item":"Ginger garlic paste","quantity":"1 tablespoon"},{"item":"Tomato","quantity":"2 medium"},{"item":"Red chili powder","quantity":"1 teaspoon"},{"item":"Turmeric powder","quantity":"0.5 teaspoon"},{"item":"Coriander powder","quantity":"1 teaspoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Garam masala","quantity":"0.5 teaspoon"},{"item":"Water","quantity":"0.5 cup"}]'::jsonb, '["Wash the spinach thoroughly and chop it roughly.","Peel the potatoes and cut them into medium-sized cubes.","Heat oil in a pot and add finely sliced onion until golden brown.","Add ginger garlic paste and fry for a minute.","Add chopped tomatoes, red chili powder, turmeric powder, coriander powder, and salt.","Cook the masala until oil separates from the mixture.","Add the potato cubes and stir well for two minutes.","Add chopped spinach and mix everything together.","Pour in half a cup of water, cover the pot, and cook on low heat until potatoes are tender and spinach is soft.","Remove the lid and sauté on high heat for a few minutes to dry excess moisture.","Sprinkle garam masala powder on top and mix gently.","Serve hot with flatbread or rice."]'::jsonb, true),
  ('mixed-sabzi', 'Pakistani Mixed Sabzi', (select id from public.dishes where slug = 'mixed-sabzi'), 45, 4, '[{"item":"potatoes","quantity":"2 medium"},{"item":"cauliflower florets","quantity":"2 cups"},{"item":"carrots","quantity":"1 cup sliced"},{"item":"peas","quantity":"1 cup"},{"item":"cooking oil","quantity":"1/3 cup"},{"item":"onion","quantity":"1 medium chopped"},{"item":"tomatoes","quantity":"2 chopped"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"turmeric powder","quantity":"1/2 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"fresh coriander","quantity":"1/4 cup chopped"}]'::jsonb, '["Heat oil in a pan and fry the chopped onions until golden brown.","Add ginger garlic paste and sauté for one minute.","Stir in the chopped tomatoes, red chili powder, turmeric powder, and salt.","Cook the masala until the tomatoes are soft and oil separates from the sides.","Add the potatoes and carrots, mixing well with the masala.","Cover and cook on low heat for ten minutes.","Add the cauliflower florets and peas, stirring gently.","Cover again and let all the vegetables simmer on low heat until tender.","Garnish with fresh coriander and serve hot with flatbread."]'::jsonb, true),
  ('khichdi', 'Traditional Pakistani Khichdi', (select id from public.dishes where slug = 'khichdi'), 35, 4, '[{"item":"white rice","quantity":"1 cup"},{"item":"yellow moong dal","quantity":"1/2 cup"},{"item":"ghee or cooking oil","quantity":"3 tablespoons"},{"item":"cumin seeds","quantity":"1 teaspoon"},{"item":"onion","quantity":"1 medium"},{"item":"ginger garlic paste","quantity":"1 tablespoon"},{"item":"turmeric powder","quantity":"1/2 teaspoon"},{"item":"salt","quantity":"1 teaspoon"},{"item":"water","quantity":"4 cups"}]'::jsonb, '["Rinse the rice and yellow moong dal together in water until the water runs clear, then soak them for twenty minutes.","Heat ghee in a pressure cooker or a heavy-bottomed pot over medium heat.","Add the cumin seeds and let them sizzle for a few seconds.","Add the sliced onion and fry until it turns light golden brown.","Stir in the ginger garlic paste and cook for one minute until the raw aroma disappears.","Add the turmeric powder and salt, mixing well with the onions.","Drain the soaked rice and dal, then add them into the pot.","Pour in four cups of water and give everything a good stir.","Cover with a lid and cook on medium-low heat until the rice and dal are very soft and well combined, stirring occasionally.","Remove from heat, drizzle with a little extra ghee if desired, and serve hot."]'::jsonb, true),
  ('kadhi-pakora', 'Pakistani Kadhi Pakora', (select id from public.dishes where slug = 'kadhi-pakora'), 60, 4, '[{"item":"yogurt","quantity":"2 cups"},{"item":"gram flour","quantity":"1.5 cups"},{"item":"turmeric powder","quantity":"1 teaspoon"},{"item":"red chili powder","quantity":"1 teaspoon"},{"item":"salt","quantity":"1.5 teaspoons"},{"item":"onion","quantity":"2 medium"},{"item":"green chilies","quantity":"3 chopped"},{"item":"fresh coriander","quantity":"0.5 cup"},{"item":"cumin seeds","quantity":"1 teaspoon"},{"item":"oil","quantity":"0.5 cup"},{"item":"water","quantity":"6 cups"},{"item":"whole dried red chilies","quantity":"3"}]'::jsonb, '["Whisk yogurt, half cup gram flour, turmeric, red chili powder, and salt together with water to make a smooth base.","Pour the yogurt mixture into a large pot and bring it to a boil, then simmer on low heat for forty minutes.","Prepare the pakora batter by mixing the remaining gram flour, sliced onion, green chilies, coriander, salt, and a little water.","Drop spoonfuls of the pakora batter into hot oil and fry until golden brown, then set aside.","Add the fried pakoras into the simmering kadhi and cook for five more minutes.","In a separate pan, heat a little oil with cumin seeds and whole red chilies to make the tempering.","Pour the tempering over the kadhi and serve hot with boiled rice."]'::jsonb, true),
  ('egg-fried-rice', 'Pakistani Style Egg Fried Rice', (select id from public.dishes where slug = 'egg-fried-rice'), 30, 4, '[{"item":"Basmati rice","quantity":"2 cups"},{"item":"Eggs","quantity":"3"},{"item":"Carrot","quantity":"1 medium, finely diced"},{"item":"Green beans","quantity":"half cup, chopped"},{"item":"Spring onions","quantity":"half cup, chopped"},{"item":"Garlic paste","quantity":"1 teaspoon"},{"item":"White pepper powder","quantity":"half teaspoon"},{"item":"Salt","quantity":"1 teaspoon"},{"item":"Cooking oil","quantity":"4 tablespoons"}]'::jsonb, '["Soak the basmati rice in water for 20 minutes, then boil until fully cooked and drain.","Beat the eggs in a bowl with a pinch of salt.","Heat 1 tablespoon of oil in a large wok and scramble the eggs, then remove and set aside.","In the same wok, add the remaining oil and sauté the garlic paste for 30 seconds.","Add the diced carrots and green beans, stir-frying on high heat for 3 minutes.","Add the white pepper and salt, mixing well with the vegetables.","Add the boiled rice and gently fold everything together to avoid breaking the grains.","Toss in the scrambled eggs and chopped spring onions, mix thoroughly, cover, and let it steam on low heat for 5 minutes before serving."]'::jsonb, true),
  ('raita', 'Desi Cucumber Raita', (select id from public.dishes where slug = 'raita'), 10, 4, '[{"item":"Plain yogurt","quantity":"2 cups"},{"item":"Cucumber","quantity":"1 medium"},{"item":"Roasted cumin powder","quantity":"1 teaspoon"},{"item":"Black salt","quantity":"1/2 teaspoon"},{"item":"Fresh coriander leaves","quantity":"2 tablespoons"},{"item":"Green chili","quantity":"1 small"},{"item":"Salt","quantity":"to taste"}]'::jsonb, '["Whisk the plain yogurt in a bowl until smooth.","Peel and finely chop or grate the cucumber.","Finely chop the fresh coriander leaves and the green chili.","Add the cucumber, coriander, and green chili to the whipped yogurt.","Mix in the roasted cumin powder, black salt, and regular salt.","Stir everything together well and chill in the refrigerator before serving."]'::jsonb, true)
